"""PL-03 step 2: whole-period summary."""

from __future__ import annotations

from statistics import fmean, stdev

from risk.types import TickerSummary, VolSeries


def summary_stats(vol: VolSeries, periods_per_year: int = 252) -> tuple[TickerSummary, ...]:
    """One summary per ticker; `ValueError` with fewer than two returns.

    Spine version: `ann_return` and `ann_vol` hold the daily mean and sample stdev of the
    returns, not yet annualized; `sharpe` is their ratio (0 when the stdev is 0).
    """
    if len(vol.returns.dates) < 2:
        raise ValueError(f"summary_stats needs at least two returns, got {len(vol.returns.dates)}")
    summaries = []
    for ticker in vol.returns.tickers:
        returns = vol.returns.values[ticker]
        mean = fmean(returns)
        spread = stdev(returns)
        summaries.append(
            TickerSummary(
                ticker=ticker,
                ann_return=mean,
                ann_vol=spread,
                sharpe=mean / spread if spread else 0.0,
                last_vol=vol.values[ticker][-1],
            )
        )
    return tuple(summaries)
"""summary_stats spine: daily mean and sample stdev per ticker."""

from __future__ import annotations

import math

import pytest

from risk import Returns, TickerSummary, VolSeries
from risk.summary import summary_stats


def _vol(
    values: dict[str, tuple[float, ...]], vols: dict[str, tuple[float | None, ...]]
) -> VolSeries:
    dates = tuple(f"2024-01-{day:02d}" for day in range(3, 3 + len(next(iter(values.values())))))
    returns = Returns(base_date="2024-01-02", dates=dates, tickers=tuple(values), values=values)
    return VolSeries(returns=returns, window=2, annualized=True, values=vols)


def _from_sample(data: dict) -> VolSeries:
    r = data["returns"]
    returns = Returns(
        base_date=r["base_date"],
        dates=tuple(r["dates"]),
        tickers=tuple(r["tickers"]),
        values={t: tuple(v) for t, v in r["values"].items()},
    )
    return VolSeries(
        returns=returns,
        window=data["window"],
        annualized=data["annualized"],
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def test_sample_gives_one_summary_per_ticker_in_order(contract_sample):
    summaries = summary_stats(_from_sample(contract_sample("risk.VolSeries")))
    assert [s.ticker for s in summaries] == ["AAA", "BBB"]
    assert all(isinstance(s, TickerSummary) for s in summaries)
    aaa, bbb = summaries
    assert aaa.ann_return == pytest.approx(0.0188217534 / 5)
    assert aaa.last_vol == pytest.approx(0.2011759)
    assert bbb.last_vol == pytest.approx(0.2914308)
    assert all(math.isfinite(s.ann_vol) and s.ann_vol > 0 for s in summaries)


def test_mean_stdev_and_ratio():
    (summary,) = summary_stats(_vol({"AAA": (0.01, 0.03)}, {"AAA": (None, None)}))
    assert summary.ann_return == pytest.approx(0.02)
    assert summary.ann_vol == pytest.approx(math.sqrt(2) / 100)
    assert summary.sharpe == pytest.approx(0.02 / (math.sqrt(2) / 100))
    assert summary.last_vol is None


def test_flat_returns_give_zero_sharpe():
    (summary,) = summary_stats(_vol({"AAA": (0.01, 0.01, 0.01)}, {"AAA": (None, None, 0.0)}))
    assert summary.ann_vol == 0.0
    assert summary.sharpe == 0.0
    assert summary.last_vol == 0.0


def test_fewer_than_two_returns_is_an_error():
    with pytest.raises(ValueError, match="at least two returns"):
        summary_stats(_vol({"AAA": (0.01,)}, {"AAA": (None,)}))
"""Intent tests for M1-T19: risk.summary_stats, the whole-period summary (RISK-04, TC-07)."""

from __future__ import annotations

import pytest

from risk import Returns, TickerSummary, VolSeries, summary_stats


def _returns(data: dict) -> Returns:
    return Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def _vol(data: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(data["returns"]),
        window=data["window"],
        annualized=data["annualized"],
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def _by_ticker(summaries: tuple[TickerSummary, ...]) -> dict[str, TickerSummary]:
    return {s.ticker: s for s in summaries}


@pytest.mark.intent
def test_tc07_one_summary_per_ticker(golden):
    data, expected = golden("risk", "TC-07")
    result = summary_stats(_vol(data["vol"]))
    assert isinstance(result, tuple)
    assert all(isinstance(s, TickerSummary) for s in result)
    assert [s.ticker for s in result] == [row["ticker"] for row in expected["summary"]]


@pytest.mark.intent
@pytest.mark.parametrize("field", ["ann_return", "ann_vol", "sharpe"])
def test_tc07_annualized_figures(golden, field):
    data, expected = golden("risk", "TC-07")
    got = _by_ticker(summary_stats(_vol(data["vol"])))
    for row in expected["summary"]:
        actual = getattr(got[row["ticker"]], field)
        assert actual == pytest.approx(row[field], abs=expected["tol"]), row["ticker"]


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe(golden):
    data, expected = golden("risk", "TC-07")
    got = _by_ticker(summary_stats(_vol(data["vol"])))
    flat = next(row for row in expected["summary"] if row["ann_vol"] == 0)
    assert got[flat["ticker"]].ann_vol == pytest.approx(0.0, abs=expected["tol"])
    assert got[flat["ticker"]].sharpe == pytest.approx(flat["sharpe"], abs=expected["tol"])


@pytest.mark.intent
def test_tc07_last_rolling_vol(golden):
    data, expected = golden("risk", "TC-07")
    got = _by_ticker(summary_stats(_vol(data["vol"])))
    for row in expected["summary"]:
        last_vol = got[row["ticker"]].last_vol
        assert last_vol is not None, row["ticker"]
        assert last_vol == pytest.approx(row["last_vol"], abs=expected["tol"]), row["ticker"]


@pytest.mark.intent
def test_explicit_periods_per_year_252_matches_default(golden):
    data, expected = golden("risk", "TC-07")
    got = _by_ticker(summary_stats(_vol(data["vol"]), periods_per_year=252))
    for row in expected["summary"]:
        summary = got[row["ticker"]]
        assert summary.ann_return == pytest.approx(row["ann_return"], abs=expected["tol"])
        assert summary.ann_vol == pytest.approx(row["ann_vol"], abs=expected["tol"])


@pytest.mark.intent
def test_fewer_than_two_returns_is_rejected(golden):
    data, _ = golden("risk", "TC-07")
    vol = data["vol"]
    short = {
        "returns": {
            "base_date": vol["returns"]["base_date"],
            "dates": vol["returns"]["dates"][:1],
            "tickers": vol["returns"]["tickers"],
            "values": {t: v[:1] for t, v in vol["returns"]["values"].items()},
        },
        "window": vol["window"],
        "annualized": vol["annualized"],
        "values": {t: v[:1] for t, v in vol["values"].items()},
    }
    with pytest.raises(ValueError, match=r"(?i)two|2|return"):
        summary_stats(_vol(short))
"""risk's boundary types: returns, volatility, summaries, drawdowns and the report."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class Returns:
    """Daily log returns on the prices' dates after the first, which is `base_date`."""

    base_date: str
    dates: tuple[str, ...]
    tickers: tuple[str, ...]
    values: Mapping[str, tuple[float, ...]]


@dataclass(frozen=True)
class VolSeries:
    """Rolling volatility aligned to `returns.dates`; None until `window` earlier returns exist."""

    returns: Returns
    window: int
    annualized: bool
    values: Mapping[str, tuple[float | None, ...]]


@dataclass(frozen=True)
class TickerSummary:
    """One ticker's whole-period statistics."""

    ticker: str
    ann_return: float
    ann_vol: float
    sharpe: float
    last_vol: float | None


@dataclass(frozen=True)
class Drawdown:
    """A ticker's worst fall from a peak: `depth` <= 0 (trough / peak - 1).

    `peak_date` <= `trough_date`; with no fall `depth` is 0 and both dates are `base_date`.
    """

    ticker: str
    depth: float
    peak_date: str
    trough_date: str


@dataclass(frozen=True)
class Report:
    """The written report: one row per ticker, sorted; the same rows as the file at `path`."""

    path: str
    rows: tuple[Mapping[str, object], ...]
"""PL-02 step 4: annualize volatility."""

from __future__ import annotations

import math
from dataclasses import replace

from risk.types import VolSeries


def annualize(vol: VolSeries, periods_per_year: int = 252) -> VolSeries:
    """Volatility scaled to a year of trading days (daily vol * sqrt(periods_per_year)); `ValueError` if already annualized.

    Gaps (None) stay gaps.
    """
    if vol.annualized:
        raise ValueError("volatility is already annualized")
    scale = math.sqrt(periods_per_year)
    values = {
        ticker: tuple(None if v is None else v * scale for v in series)
        for ticker, series in vol.values.items()
    }
    return replace(vol, annualized=True, values=values)
"""PL-02 step 3: rolling volatility."""

from __future__ import annotations

from statistics import stdev

from risk.types import Returns, VolSeries


def rolling_vol(returns: Returns, window: int) -> VolSeries:
    """Volatility of the `window` returns before each date; `ValueError` if `window` < 2.

    The value at date i is the sample stdev (n - 1) of returns i - window .. i - 1, never
    date i's own return; None until `window` earlier returns exist.
    """
    if window < 2:
        raise ValueError(f"window must be at least 2, got {window}")
    values = {
        ticker: tuple(
            stdev(series[i - window : i]) if i >= window else None for i in range(len(series))
        )
        for ticker, series in returns.values.items()
    }
    return VolSeries(returns=returns, window=window, annualized=False, values=values)
